#ifndef WOLF_H
#define WOLF_H

#include <string>

struct Wolf {
    int health = 100; // 0-100
    int hunger = 0;   // 0-100
    int energy = 100; // 0-100
    int reputation = 0; // 0-100
    int spirit = 50;   // 0-100, wolf spirit/morale

    bool isAlive() const {
        return health > 0 && hunger < 100;
    }

    void updateHunger(int amount) {
        hunger += amount;
        if (hunger < 0) hunger = 0;
        if (hunger > 100) hunger = 100;
        if (hunger > 80) health -= 5; // Hunger affects health
        if (health < 0) health = 0;
    }

    void updateEnergy(int amount) {
        energy += amount;
        if (energy < 0) energy = 0;
        if (energy > 100) energy = 100;
    }

    void updateHealth(int amount) {
        health += amount;
        if (health < 0) health = 0;
        if (health > 100) health = 100;
    }

    void updateReputation(int amount) {
        reputation += amount;
        if (reputation < 0) reputation = 0;
        if (reputation > 100) reputation = 100;
    }

    void updateSpirit(int amount) {
        spirit += amount;
        if (spirit < 0) spirit = 0;
        if (spirit > 100) spirit = 100;
    }

    // Validation functions
    bool canMakeChoice(int energyReq = 0) const {
        return health > 0 && hunger < 100 && energy >= energyReq;
    }

    // Pack benefit functions
    int getPackBenefit() const { // Calculate benefits from pack members
        // This function will be called from elsewhere where Pack is available
        // For now, we'll return a placeholder - actual implementation will be in main game logic
        return 0;
    }
};

#endif

#ifndef DECISION_TREE_H
#define DECISION_TREE_H

#include <string>

struct DecisionNode {
    int scenarioID;
    std::string description;
    std::string choiceA_text;
    std::string choiceB_text;
    DecisionNode* left;  // Choice A
    DecisionNode* right; // Choice B
    bool isEnding;
    std::string endingText;
};

class DecisionTree {
private:
    DecisionNode* root;
    DecisionNode* currentNode;
    void deleteTree(DecisionNode* node);  // Helper for destructor
public:
    DecisionTree();
    ~DecisionTree();
    void insertNode(DecisionNode* parent, DecisionNode* child, bool isLeft);
    DecisionNode* getCurrentNode() const;
    void setCurrentNode(DecisionNode* node);
    DecisionNode* getRoot();
    void buildSampleTree();
    DecisionNode* findNodeById(int id);  // Add function to find node by ID
};

#endif

#include "../include/decision_tree.h"
#include <iostream>
#include <functional>

DecisionTree::DecisionTree() : root(nullptr), currentNode(nullptr) {}

DecisionTree::~DecisionTree() {
    deleteTree(root);
}

void DecisionTree::deleteTree(DecisionNode* node) {
    if (node) {
        deleteTree(node->left);
        deleteTree(node->right);
        delete node;
    }
}

void DecisionTree::insertNode(DecisionNode* parent, DecisionNode* child, bool isLeft) {
    if (isLeft) {
        parent->left = child;
    } else {
        parent->right = child;
    }
}

DecisionNode* DecisionTree::getCurrentNode() const {
    return currentNode;
}

DecisionNode* DecisionTree::getRoot() {
    return root;
}

void DecisionTree::setCurrentNode(DecisionNode* node) {
    currentNode = node;
}

