DecisionNode* DecisionTree::findNodeById(int id) {
    // Helper function to recursively find a node by ID
    std::function<DecisionNode*(DecisionNode*)> search = [&](DecisionNode* node) -> DecisionNode* {
        if (!node) return nullptr;
        if (node->scenarioID == id) return node;

        DecisionNode* found = search(node->left);
        if (found) return found;

        return search(node->right);
    };

    return search(root);
}

#ifndef PRIORITY_QUEUE_H
#define PRIORITY_QUEUE_H

#include <string>
#include <vector>
#include <functional>

// Forward declaration
struct Wolf;

struct Event {
    std::string name;
    int priority; // 1-3, lower is more urgent
    std::string description;

    // Use std::function for proper Wolf effect
    std::function<void(Wolf&)> effect;

    bool operator>(const Event& other) const {
        return priority > other.priority;
    }
    bool operator<(const Event& other) const {
        return priority < other.priority;
    }
};

class PriorityQueue {
private:
    std::vector<Event> heap;
    void heapifyUp(int index);
    void heapifyDown(int index);
public:
    void insert(Event e);
    Event extractMin();
    bool isEmpty();
    int size(); // Add size function for event cycling
};

#endif

#include "../include/priority_queue.h"
#include <stdexcept>

void PriorityQueue::heapifyUp(int index) {
    while (index > 0) {
        int parent = (index - 1) / 2;
        if (heap[index].priority > heap[parent].priority) break;
        std::swap(heap[index], heap[parent]);
        index = parent;
    }
}

void PriorityQueue::heapifyDown(int index) {
    int size = heap.size();
    while (true) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int smallest = index;
        if (left < size && heap[left].priority < heap[smallest].priority) smallest = left;
        if (right < size && heap[right].priority < heap[smallest].priority) smallest = right;
        if (smallest == index) break;
        std::swap(heap[index], heap[smallest]);
        index = smallest;
    }
}

void PriorityQueue::insert(Event e) {
    heap.push_back(e);
    heapifyUp(heap.size() - 1);
}

Event PriorityQueue::extractMin() {
    if (heap.empty()) throw std::runtime_error("Heap is empty");
    Event min = heap[0];
    heap[0] = heap.back();
    heap.pop_back();
    if (!heap.empty()) heapifyDown(0);
    return min;
}

bool PriorityQueue::isEmpty() {
    return heap.empty();
}

int PriorityQueue::size() {
    return heap.size();
}

#ifndef GAME_STACK_H
#define GAME_STACK_H

#include <vector>

struct DecisionNode; // Forward
struct Item; // Forward declaration for inventory
class Inventory; // Forward declaration for inventory

struct GameState {
    DecisionNode* currentNode;
    int health, hunger, energy;
    int day;           // Add day field
    Item* inventoryHead; // Add inventory head for restoration (changed back to original)
};

class GameStack {
private:
    std::vector<GameState> stack;
    const int maxSize = 5;
public:
    GameStack();  // Add constructor
    ~GameStack(); // Add destructor
    void push(GameState gs);
    GameState pop();
    bool isEmpty();
    int size();
    int getMaxSize(); // Add getter for max size
};

#endif

#include "../include/game_stack.h"
#include <stdexcept>

GameStack::GameStack() {
    // Constructor - nothing special needed
}

GameStack::~GameStack() {
    // Destructor - no need to clean up inventoryHead since it's just a pointer to existing inventory
    // The inventory is managed elsewhere
}

void GameStack::push(GameState gs) {
    if (stack.size() >= maxSize) {
        // Remove oldest without deleting inventoryHead since it's just a pointer
        stack.erase(stack.begin()); // Remove oldest
    }
    stack.push_back(gs);
}

GameState GameStack::pop() {
    if (stack.empty()) throw std::runtime_error("Stack is empty");
    GameState gs = stack.back();
    stack.pop_back();
    return gs;
}

bool GameStack::isEmpty() {
    return stack.empty();
}

int GameStack::size() {
    return stack.size();
}

int GameStack::getMaxSize() {
    return maxSize;
}

#ifndef INVENTORY_H
#define INVENTORY_H

#include <string>
#include "wolf.h"

enum ItemType { FOOD, HERB, TOOL };

struct Item {
    std::string name;
    ItemType type;
    int effect;
    int quantity;
    Item* next;
};

class Inventory {
private:
    Item* head;
    int count;
public:
    Inventory();
    ~Inventory();
    bool addItem(std::string name, ItemType type, int effect, int qty);
    bool useItem(std::string name);
    void displayInventory();
    bool isFull() const;
    Item* getHead() const;
    Inventory* clone() const; // Add method to create a deep copy of the inventory
    void replaceWith(Inventory* other); // Add method to replace contents with another inventory
    bool useItem(std::string name, Wolf& wolf); // Add method to use item and apply effect to wolf
};

#endif

#include "../include/inventory.h"
#include <iostream>

Inventory::Inventory() : head(nullptr), count(0) {}

Inventory::~Inventory() {
    Item* current = head;
    while (current) {
        Item* next = current->next;
        delete current;
        current = next;
    }
}

bool Inventory::addItem(std::string name, ItemType type, int effect, int qty) {
    if (count >= 10) return false;
    Item* newItem = new Item{name, type, effect, qty, nullptr};
    if (!head) {
        head = newItem;
    } else {
        Item* current = head;
        while (current->next) current = current->next;
        current->next = newItem;
    }
    count++;
    return true;
}

bool Inventory::useItem(std::string name) {
    Item* current = head;
    Item* prev = nullptr;
    while (current) {
        if (current->name == name) {
            // Apply effect (assume wolf is passed, but for now just remove)
            if (current->quantity > 1) {
                current->quantity--;
            } else {
                if (prev) prev->next = current->next;
                else head = current->next;
                delete current;
                count--;
            }
            return true;
        }
        prev = current;
        current = current->next;
    }
    return false;
}

void Inventory::displayInventory() {
    Item* current = head;
    while (current) {
        std::cout << current->name << " (x" << current->quantity << ")" << std::endl;
        current = current->next;
    }
}

bool Inventory::isFull() const {
    return count >= 10;
}

Item* Inventory::getHead() const {
    return head;
}

Inventory* Inventory::clone() const {
    Inventory* newInventory = new Inventory();
    Item* current = head;
    while (current) {
        newInventory->addItem(current->name, current->type, current->effect, current->quantity);
        current = current->next;
    }
    return newInventory;
}

void Inventory::replaceWith(Inventory* other) {
    // Clear current inventory
    Item* current = head;
    while (current) {
        Item* next = current->next;
        delete current;
        current = next;
    }
    head = nullptr;
    count = 0;

    // Copy items from other inventory
    if (other && other->head) {
        Item* otherCurrent = other->head;
        while (otherCurrent) {
            addItem(otherCurrent->name, otherCurrent->type, otherCurrent->effect, otherCurrent->quantity);
            otherCurrent = otherCurrent->next;
        }
    }
}

bool Inventory::useItem(std::string name, Wolf& wolf) {
    Item* current = head;
    Item* prev = nullptr;
    while (current) {
        if (current->name == name) {
            // Apply the item's effect to the wolf based on its type
            if (current->type == FOOD) {
                wolf.updateHunger(current->effect);
            } else if (current->type == HERB) {
                wolf.updateHealth(current->effect);
            } else if (current->type == TOOL) {
                // Tools might provide other benefits (e.g., energy boost, reputation)
                // For now, we'll add a small energy boost
                wolf.updateEnergy(current->effect);
            }

            // Reduce quantity or remove item
            if (current->quantity > 1) {
                current->quantity--;
            } else {
                // Remove the item from the list
                if (prev) {
                    prev->next = current->next;
                } else {
                    head = current->next;
                }
                delete current;
                count--;
            }
            return true;
        }
        prev = current;
        current = current->next;
    }
    return false; // Item not found
}

